<?php $__env->startSection('title','Wishlist'); ?>
<?php $__env->startSection('content'); ?>
<section class="customer-card"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="mb-0">My Wishlist</h2><a class="customer-action" href="/products">Continue shopping</a></div><div class="wishlist-grid"><?php $__empty_1 = true; $__currentLoopData = $items; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $item): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><article class="wishlist-product"><?php if($item->product?->thumbnail): ?><img src="<?php echo e($item->product->thumbnail->url); ?>" alt="<?php echo e($item->product->name); ?>"><?php else: ?><div class="wishlist-placeholder"><i class="bi bi-image"></i></div><?php endif; ?><div><b><?php echo e($item->product?->name); ?></b><span>$<?php echo e(number_format($item->product?->selling_price ?? 0,2)); ?></span><small class="text-muted"><?php echo e($item->product?->stock_quantity ? 'In stock' : 'Out of stock'); ?></small></div><form method="POST" action="<?php echo e(route('customer.wishlist.remove',$item->product_id)); ?>"><?php echo csrf_field(); ?> <?php echo method_field('DELETE'); ?><button class="customer-action danger" title="Remove from wishlist"><i class="bi bi-trash"></i> Remove</button></form></article><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><div class="customer-empty"><i class="bi bi-heart"></i><p>Your wishlist is empty.</p><a class="customer-action primary mt-3" href="/products">Browse products</a></div><?php endif; ?></div><div class="mt-3"><?php echo e($items->links()); ?></div></section>
<?php $__env->stopSection(); ?>

